function doc(lang, kicker, title, rows) {
  const mail = '[dmitry8.work@gmail.com](mailto:dmitry8.work@gmail.com)';
  const dateLabel = {
    ja: '**施行日:** 2026年11月18日',
    zh: '**生效日期：** 2026年11月18日',
    ko: '**시행일:** 2026년 11월 18일',
    ru: '**Дата вступления в силу:** 18 ноября 2026 г.',
    de: '**Gültig ab:** 18. November 2026',
    es: '**Fecha de entrada en vigor:** 18 de noviembre de 2026',
    fr: '**Date d’entrée en vigueur :** 18 novembre 2026',
  }[lang];
  const devLabel = {
    ja: '**開発者:** Dmitry Sinkevich',
    zh: '**开发者：** Dmitry Sinkevich',
    ko: '**개발자:** Dmitry Sinkevich',
    ru: '**Разработчик:** Dmitry Sinkevich',
    de: '**Entwickler:** Dmitry Sinkevich',
    es: '**Desarrollador:** Dmitry Sinkevich',
    fr: '**Développeur :** Dmitry Sinkevich',
  }[lang];
  const contactLabel = {
    ja: `**連絡先:** ${mail}`,
    zh: `**联系方式：** ${mail}`,
    ko: `**연락처:** ${mail}`,
    ru: `**Контакт:** ${mail}`,
    de: `**Kontakt:** ${mail}`,
    es: `**Contacto:** ${mail}`,
    fr: `**Contact :** ${mail}`,
  }[lang];
  const blocks = rows.map((row) => {
    if (row.length === 1 || (row.length === 2 && !row[0].match(/^\d/))) {
      return { p: row };
    }
    const [h, p, ul] = row;
    if (ul) return { h, p, ul };
    return { h, p };
  });
  return { kicker, title, meta: [dateLabel, devLabel, contactLabel], blocks };
}
